import math

def check_expression(n):
    if n < 0:
        return None # Should not happen for non-negative integers

    denominator = 2 * n - 1

    # Handle n=0 case where denominator is -1
    if n == 0:
        numerator = 3 * (math.factorial(0 + 2) + 1)
        return numerator / denominator

    if denominator == 0:
        return None # Should not happen for integer n

    try:
        numerator = 3 * (math.factorial(n + 2) + 1)
        return numerator / denominator
    except OverflowError:
        return "Too large"

n_test = 12
result = check_expression(n_test)
print(f"E({n_test}) = {result}")
print(f"Is integer? {result == int(result)}")
